<style>
.fk-search{display:flex;flex-wrap:wrap;align-items:end;gap:14px}.fk-search .field{flex:1 1 170px;min-width:0;margin:0}.fk-search .field:first-child{flex:2 1 240px}.fk-search .actions{flex:0 0 auto}
.fk-list-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;margin:24px 0 14px}.fk-list-heading h2{font-size:20px;margin:0;color:#15477a}.fk-list-heading span{color:#536a7d;font-size:14px}
.fk-faq{border:1px solid #cfdeec;border-radius:6px;margin-bottom:12px;background:#fff}.fk-faq:nth-child(even){background:#f0f8f5;border-color:#c5dfd8}.fk-faq summary{display:flex;align-items:center;gap:16px;padding:20px;cursor:pointer;list-style:none}.fk-faq summary::-webkit-details-marker{display:none}.fk-faq summary>svg{width:23px;height:23px;flex-shrink:0;color:#0f766e}.fk-faq summary span{min-width:0;flex:1}.fk-faq summary small{display:block;color:#566d80;margin-bottom:6px;font-size:13px}.fk-faq summary strong{font-size:17px;line-height:1.5;color:#15477a;overflow-wrap:anywhere}.fk-faq[open] .fk-chevron{transform:rotate(180deg)}.fk-answer{border-top:1px solid #d8e4e7;padding:0 20px 20px 59px}.fk-prose{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8}.ho-band .fk-question{margin-top:18px;font-size:23px;display:block;overflow-wrap:anywhere}
.fk-meta{display:flex;flex-wrap:wrap;gap:12px 24px;color:#52687a;font-size:14px;margin:16px 0}.fk-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:20px 0}.fk-stat{border:1px solid #cfdeec;background:#edf4fc;padding:16px;border-radius:6px;min-width:0}.fk-stat:nth-child(3n+2){background:#e7f4f0;border-color:#c1dfd6}.fk-stat:nth-child(3n){background:#fff8dc;border-color:#ead88b}.fk-stat strong{display:block;font-size:28px;color:#15477a;margin:8px 0}.fk-stat small{display:block;color:#536a7d;line-height:1.5;font-size:12px}.fk-action{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:end;gap:16px}.fk-action .field{margin:0}.fk-audit{margin-top:24px}.fk-narrative h3{font-size:17px;color:#15477a;margin:22px 0 8px}.fk-scroll{overflow-x:auto;max-width:100%;margin-bottom:22px}.fk-month{width:100%;border-collapse:collapse;min-width:560px}.fk-month th,.fk-month td{padding:12px;border:1px solid #d9e4ec;text-align:right}.fk-month th{background:#edf4fc}.fk-month th:first-child,.fk-month td:first-child{text-align:left}
@media(max-width:1000px){.fk-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.fk-action{grid-template-columns:minmax(0,1fr)}}
@media(max-width:620px){.fk-faq summary{padding:16px;gap:12px}.fk-faq summary strong{font-size:16px}.fk-answer{padding:0 16px 16px}.fk-list-heading{display:block}.fk-list-heading span{display:block;margin-top:8px}.fk-stats{gap:8px}.fk-stat{padding:12px}.fk-stat strong{font-size:25px}.fk-search .actions{flex-wrap:wrap}.ho-band .fk-question{font-size:21px}}
@media(max-width:620px){.fk-search .field,.fk-search .field:first-child,.fk-search .actions{flex-basis:100%}.fk-search .actions{justify-content:flex-start}}
</style>
